#!/usr/bin/env python3
"""A small persistent HTTP key-value service using only the standard library."""

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import unquote


MAX_BODY_BYTES = 1024 * 1024


class Store:
    def __init__(self, path: str):
        self.path = Path(path)
        self.lock = threading.RLock()
        self.entries = {}
        self._load()

    def _load(self):
        try:
            with self.path.open(encoding="utf-8") as file:
                data = json.load(file)
            if not isinstance(data, dict):
                raise ValueError("root is not an object")
            self.entries = data
            self._purge_expired(persist=True)
        except FileNotFoundError:
            pass
        except (OSError, ValueError, json.JSONDecodeError) as error:
            print(f"Could not load data file: {error}", file=sys.stderr)

    def _purge_expired(self, persist=False):
        now = time.time()
        expired = [key for key, item in self.entries.items()
                   if not isinstance(item, dict) or item.get("expires_at") is not None and item["expires_at"] <= now]
        for key in expired:
            self.entries.pop(key, None)
        if expired and persist:
            self._save()
        return bool(expired)

    def _save(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary = tempfile.mkstemp(prefix=f".{self.path.name}.", dir=self.path.parent, text=True)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as file:
                json.dump(self.entries, file, ensure_ascii=False, separators=(",", ":"))
                file.flush()
                os.fsync(file.fileno())
            os.replace(temporary, self.path)
        except Exception:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def get(self, key):
        with self.lock:
            if self._purge_expired():
                self._save()
            item = self.entries.get(key)
            return None if item is None else item["value"]

    def put(self, key, value, ttl):
        with self.lock:
            if self._purge_expired():
                self._save()
            created = key not in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl is None else time.time() + ttl}
            self._save()
            return created

    def delete(self, key):
        with self.lock:
            if self._purge_expired():
                self._save()
            if key not in self.entries:
                return False
            del self.entries[key]
            self._save()
            return True

    def keys(self):
        with self.lock:
            if self._purge_expired():
                self._save()
            return sorted(self.entries)


def parse_key(path):
    prefix = "/v1/kv/"
    if not path.startswith(prefix):
        return None
    encoded = path[len(prefix):]
    if not encoded or "/" in encoded:
        raise ValueError("key must be non-empty and cannot contain '/'")
    try:
        key = unquote(encoded, encoding="utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise ValueError("key must be valid UTF-8") from error
    if not key or "/" in key:
        raise ValueError("key must be non-empty and cannot contain '/'")
    return key


class Handler(BaseHTTPRequestHandler):
    store = None

    def log_message(self, format, *args):
        print(f"{self.address_string()} - {format % args}", file=sys.stderr)

    def _json(self, status, payload=None):
        self.send_response(status)
        if payload is not None:
            raw = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(raw)))
        else:
            raw = b""
            self.send_header("Content-Length", "0")
        self.end_headers()
        self.wfile.write(raw)

    def _error(self, status, message):
        self._json(status, {"error": message})

    def _key(self):
        try:
            return parse_key(self.path.split("?", 1)[0])
        except ValueError as error:
            self._error(400, str(error))
            return False

    def do_GET(self):
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self._json(200, {"status": "ok"})
            return
        if path == "/v1/keys":
            self._json(200, {"keys": self.store.keys()})
            return
        key = self._key()
        if key is None:
            self._error(404, "route not found")
        elif key is not False:
            value = self.store.get(key)
            if value is None:
                self._error(404, "key not found")
            else:
                self._json(200, {"key": key, "value": value})

    def do_DELETE(self):
        key = self._key()
        if key is None:
            self._error(404, "route not found")
        elif key is not False:
            self._json(204 if self.store.delete(key) else 404,
                       None if self.store.get(key) is not None else {"error": "key not found"})

    def do_PUT(self):
        key = self._key()
        if key is None:
            self._error(404, "route not found")
            return
        if key is False:
            return
        length = self.headers.get("Content-Length")
        try:
            length = int(length)
            if length < 0 or length > MAX_BODY_BYTES:
                raise ValueError
        except (TypeError, ValueError):
            self._error(413, "request body exceeds 1 MiB")
            return
        try:
            body = json.loads(self.rfile.read(length).decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            self._error(400, "malformed JSON")
            return
        if not isinstance(body, dict) or "value" not in body or set(body) - {"value", "ttl_seconds"}:
            self._error(400, "body must be an object with value and optional ttl_seconds")
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0):
            self._error(400, "ttl_seconds must be a finite number greater than zero")
            return
        self._json(201 if self.store.put(key, body["value"], ttl) else 200, {"key": key, "value": body["value"]})

    def do_POST(self):
        self._error(405, "method not allowed")

    def do_PATCH(self):
        self._error(405, "method not allowed")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--data", required=True)
    args = parser.parse_args()
    Handler.store = Store(args.data)
    server = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"LISTENING {server.server_port}", flush=True)
    signal.signal(signal.SIGTERM, lambda *_: server.shutdown())
    try:
        server.serve_forever()
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
